import React from "react";

const JobItem = ({ job, refreshJobs }) => {
  const handleStatusChange = async (e) => {
    await fetch(`${process.env.REACT_APP_API_URL}/api/jobs/${job._id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...job, status: e.target.value }),
    });
    refreshJobs();
  };

  const handleDelete = async () => {
    await fetch(`${process.env.REACT_APP_API_URL}/api/jobs/${job._id}`, {
      method: "DELETE",
    });
    refreshJobs();
  };

  return (
    <div className="job-card">
      <h3>{job.company}</h3>
      <p><strong>Role:</strong> {job.role}</p>
      <p><strong>Date:</strong> {job.date}</p>
      <p>
        <strong>Status:</strong>{" "}
        <select value={job.status} onChange={handleStatusChange}>
          <option>Applied</option>
          <option>Interview</option>
          <option>Offer</option>
          <option>Rejected</option>
        </select>
      </p>
      {job.link && <p><a href={job.link} target="_blank" rel="noreferrer">View Application</a></p>}
      <button onClick={handleDelete} className="delete-btn">❌ Delete</button>
    </div>
  );
};

export default JobItem;
